// AUTO-GENERATED BY silc — DO NOT EDIT
import { connect, type Socket } from "node:net";
import { join } from "node:path";

const socketPath = process.env.SILC_SOCKET || "__SOCKET_PATH__";
const port = Number(process.env.SILC_HTTP_PORT || "__PORT__");
const route = process.env.SILC_HTTP_ROUTE || "__ROUTE__";
const terminalPort = Number(process.env.SILC_TERMINAL_PORT || "__TERMINAL_PORT__");
const protocolVersion = 1;
const abiVersion = 1;
const root = import.meta.dir;
const distDir = join(root, "dist");

function encodeFrame(value: unknown): Buffer {
  const payload = Buffer.from(JSON.stringify(value));
  const frame = Buffer.allocUnsafe(6 + payload.length);
  frame.writeUInt32LE(payload.length, 0);
  frame.writeUInt16LE(protocolVersion, 4);
  payload.copy(frame, 6);
  return frame;
}

function decodeFrame(buffer: Buffer): { frame: any; rest: Buffer } | null {
  if (buffer.length < 6) return null;
  const length = buffer.readUInt32LE(0);
  const version = buffer.readUInt16LE(4);
  if (version !== protocolVersion) {
    throw new Error(`unsupported Silc protocol ${version}`);
  }
  if (buffer.length < 6 + length) return null;
  const frame = JSON.parse(buffer.subarray(6, 6 + length).toString());
  return { frame, rest: buffer.subarray(6 + length) };
}

let supervisor: Socket | null = null;
let pending = Buffer.alloc(0);
const ingestWaiters = new Map<
  string,
  { resolve: (value: any) => void; reject: (error: Error) => void }
>();

function rejectAllWaiters(error: Error) {
  for (const waiter of ingestWaiters.values()) {
    waiter.reject(error);
  }
  ingestWaiters.clear();
}

function dispatchFrames() {
  while (true) {
    const decoded = decodeFrame(pending);
    if (!decoded) break;
    pending = decoded.rest;
    const { frame } = decoded;
    if (frame.type === "RESPONSE" && typeof frame.request_id === "string") {
      const waiter = ingestWaiters.get(frame.request_id);
      if (waiter) {
        ingestWaiters.delete(frame.request_id);
        waiter.resolve(frame);
      }
    }
  }
}

function connectSupervisor(): Promise<void> {
  return new Promise((resolve, reject) => {
    supervisor = connect(socketPath);
    supervisor.on("connect", () => {
      supervisor!.write(
        encodeFrame({
          type: "HELLO",
          worker_id: "bun",
          role: "bun",
          abi_version: abiVersion,
          pid: process.pid,
        }),
      );
      supervisor!.write(encodeFrame({ type: "READY", worker_id: "bun" }));
      resolve();
    });
    supervisor.on("data", (chunk) => {
      pending = Buffer.concat([pending, chunk]);
      try {
        dispatchFrames();
      } catch (error) {
        rejectAllWaiters(error instanceof Error ? error : new Error(String(error)));
      }
    });
    supervisor.on("error", (error) => {
      rejectAllWaiters(error);
      reject(error);
    });
    supervisor.on("close", () => {
      supervisor = null;
      rejectAllWaiters(new Error("Silc supervisor closed"));
    });
  });
}

function ingest(author: string, text: string, requestId: string): Promise<any> {
  if (!supervisor) {
    return Promise.reject(new Error("supervisor socket not connected"));
  }
  return new Promise((resolve, reject) => {
    ingestWaiters.set(requestId, { resolve, reject });
    supervisor!.write(
      encodeFrame({
        type: "INGEST",
        request_id: requestId,
        author,
        text,
      }),
    );
  });
}

function contentType(pathname: string): string {
  if (pathname.endsWith(".js")) return "application/javascript; charset=utf-8";
  if (pathname.endsWith(".css")) return "text/css; charset=utf-8";
  if (pathname.endsWith(".html")) return "text/html; charset=utf-8";
  if (pathname.endsWith(".svg")) return "image/svg+xml";
  return "application/octet-stream";
}

async function serveAsset(pathname: string): Promise<Response | null> {
  const rel = pathname.replace(/^\/assets\//, "");
  if (!rel || rel.includes("..") || rel.includes("\\")) {
    return new Response("Not found", { status: 404 });
  }
  const file = Bun.file(join(distDir, rel));
  if (!(await file.exists())) {
    return null;
  }
  return new Response(file, {
    headers: { "content-type": contentType(rel) },
  });
}

type TerminalPhase = "author" | "feedback" | "waiting";
type TerminalSession = {
  phase: TerminalPhase;
  author: string;
  buffer: string;
};

function stripTelnetNegotiation(bytes: Uint8Array): Uint8Array {
  const plain: number[] = [];
  for (let i = 0; i < bytes.length; i++) {
    if (bytes[i] === 255) {
      // IAC + command + option. Subnegotiation is not needed by this simple
      // line interface, so discard the control triplet.
      i += 2;
      continue;
    }
    plain.push(bytes[i]);
  }
  return Uint8Array.from(plain);
}

function terminalBanner(socket: any) {
  socket.write(
    "\x1b[2J\x1b[HSilc Feedback Portal\r\n" +
      "Bun terminal → Silc mmap/UDS → Python → Go/SQLite\r\n" +
      "Type /quit at any prompt to disconnect.\r\n\r\n" +
      "Author: ",
  );
}

function startTerminalServer() {
  if (terminalPort <= 0) return;
  Bun.listen<TerminalSession>({
    hostname: "127.0.0.1",
    port: terminalPort,
    socket: {
      open(socket) {
        socket.data = { phase: "author", author: "", buffer: "" };
        terminalBanner(socket);
      },
      data(socket, data) {
        const session = socket.data;
        const clean = stripTelnetNegotiation(data);
        session.buffer += new TextDecoder().decode(clean).replace(/\0/g, "");
        const lines = session.buffer.split(/\r?\n/);
        session.buffer = lines.pop() || "";
        for (const raw of lines) {
          const line = raw.replace(/[\b\x7f]/g, "").trim();
          if (line === "/quit" || line === "/exit") {
            socket.write("\r\nGoodbye.\r\n");
            socket.end();
            return;
          }
          if (session.phase === "waiting") continue;
          if (session.phase === "author") {
            if (!line) {
              socket.write("Author: ");
              continue;
            }
            session.author = line.slice(0, 120);
            session.phase = "feedback";
            socket.write("Feedback: ");
            continue;
          }
          if (!line) {
            socket.write("Feedback: ");
            continue;
          }
          const text = line.slice(0, 8192);
          session.phase = "waiting";
          socket.write("\r\nSaving…\r\n");
          void ingest(session.author, text, crypto.randomUUID())
            .then((response) => {
              socket.write(`${JSON.stringify(response, null, 2)}\r\n\r\n`);
              session.author = "";
              session.phase = "author";
              socket.write("Author: ");
            })
            .catch((error) => {
              socket.write(`Error: ${String(error)}\r\n\r\n`);
              session.author = "";
              session.phase = "author";
              socket.write("Author: ");
            });
        }
      },
      error(socket, error) {
        console.error("Silc terminal socket error", error);
        socket.end();
      },
    },
  });
  console.log(`SILC_TERMINAL_READY telnet://127.0.0.1:${terminalPort}`);
}

await connectSupervisor();

Bun.serve({
  hostname: "127.0.0.1",
  port,
  async fetch(request) {
    const url = new URL(request.url);
    if (request.method === "GET" && (url.pathname === route || url.pathname === "/")) {
      const index = Bun.file(join(distDir, "index.html"));
      if (!(await index.exists())) {
        return new Response("Silc ui::web bundle missing — run silc build", { status: 500 });
      }
      return new Response(index, {
        headers: { "content-type": "text/html; charset=utf-8" },
      });
    }
    if (request.method === "GET" && url.pathname.startsWith("/assets/")) {
      return (await serveAsset(url.pathname)) || new Response("Not found", { status: 404 });
    }
    if (request.method === "GET" && url.pathname === "/health") {
      return Response.json({
        ok: true,
        ui: "web",
        substrate: "react",
      });
    }
    if (request.method === "POST" && url.pathname === "/submit") {
      const length = Number(request.headers.get("content-length") || "0");
      if (length > 16384) return Response.json({ error: "request too large" }, { status: 413 });
      try {
        const body = (await request.json()) as { author?: string; text?: string };
        const author = String(body.author || "").trim();
        const text = String(body.text || "").trim();
        if (!author || !text) {
          return Response.json({ error: "author and text are required" }, { status: 400 });
        }
        const requestId = crypto.randomUUID();
        const response = await ingest(author, text, requestId);
        return Response.json(response, { status: response.ok ? 201 : 500 });
      } catch (error) {
        return Response.json({ error: String(error) }, { status: 500 });
      }
    }
    return new Response("Not found", { status: 404 });
  },
});

startTerminalServer();
console.log(`SILC_READY http://127.0.0.1:${port}${route}`);
